<template>
  <base-layout>
    <v-toolbar
      class="grey lighten-3"
      light
      flat
      height="50"
    >
      <v-toolbar-title class="subheading">Pengaturan Print {{idJenis === 'pabean' ? 'Dokumen Pabean': idJenis === 'mutasi' ? 'Mutasi Bulanan': 'WIP'}}</v-toolbar-title>
      <v-spacer></v-spacer>
      <div>
        <v-btn
          color="primary"
          fab
          small
          dark
          @click.stop="onAdd"
        >
          <v-icon>fa-plus</v-icon>
        </v-btn>
        <v-btn
          class="indigo"
          fab
          small
          dark
          v-show="selectedRow.length == 1"
          @click.stop="onEdit"
        >
          <v-icon>fa-pencil</v-icon>
        </v-btn>
        <v-btn
          color="error"
          fab
          small
          dark
          v-show="selectedRow.length > 0"
          @click.stop="state.isDelete = !state.isDelete"
        >
          <v-icon>fa-trash</v-icon>
        </v-btn>
        <v-btn
          color="success"
          fab
          small
          dark
          @click="state.isRefresh = !state.isRefresh"
        >
          <v-icon>fa-refresh</v-icon>
        </v-btn>
      </div>
    </v-toolbar>
    <div>
      <v-card
        flat
        class="pa-3"
      >
        <table-view
          from-file="setting_print"
          :is-refresh="state.isRefresh"
          :is-delete="state.isDelete"
          :is-download="state.isDownload"
          :on-select="onSelect"
          :show-number="true"
          :extra-query-options="tableQueryOptions"
        ></table-view>
      </v-card>
    </div>
  </base-layout>
</template>

<script>
import { modal } from "@/utils/modal";

import FormAddEdit from "./FormAddEdit";

export default {
  data: () => ({
    state: {
      isAdd: false,
      isEdit: false,
      isRefresh: false,
      isDelete: false,
      isDownload: false
    },
    selectedRow: []
  }),
  methods: {
    onSelect(row) {
      this.selectedRow = row;
    },
    onAdd() {
      modal({
        name: "full-modal",
        props: {
          type: "add",
          idJenis: this.idJenis
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    },
    onEdit() {
      modal({
        name: "full-modal",
        props: {
          type: "edit",
          data: this.selectedRow[0],
          idJenis: this.idJenis
        },
        dismissable: false,
        component: FormAddEdit
      }).then(response => {
        if (response) {
          this.state.isRefresh = !this.state.isRefresh;
        }
      });
    }
  },
  created() {},
  computed: {
    idJenis() {
      let id = "pabean";
      switch (this.$route.path) {
        case "/pengaturan-print-pabean":
          id = "pabean";
          break;
        case "/pengaturan-print-mutasi":
          id = "mutasi";
          break;
        case "/pengaturan-print-wip":
          id = "wip";
          break;
        default:
          id = "pabean";
      }
      return id;
    },
    user() {
      return this.$store.state.auth.user;
    },
    tableQueryOptions() {
      return {
        jenis: this.idJenis
      };
    }
  }
};
</script>

<style lang="css" scoped>
table.table thead th,
table.table tbody td,
table.table tbody th {
  font-size: 14px !important;
}
</style>



