<template>
  <div>
    <v-toolbar
      class="indigo"
      dark
      height="50"
    >
      <v-toolbar-title>{{type=='edit' ? 'Ubah': 'Tambah'}} Pengaturan Print</v-toolbar-title>
      <v-spacer></v-spacer>
      <v-btn
        icon
        @click.native="cancel()"
        dark
      >
        <v-icon>close</v-icon>
      </v-btn>
    </v-toolbar>
    <v-flex>
      <v-form ref="form">
        <v-card
          flat
          class="pa-4"
        >
          <v-layout
            row
            wrap
          >
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                label="Periode"
                name="Periode"
                v-model="input.periode"
                :error-messages="errors.collect('Periode')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                label="Tempat"
                name="Tempat"
                v-model="input.tempat"
                :error-messages="errors.collect('Tempat')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <vdatepicker
                label="Tanggal"
                name="Tanggal"
                v-model="input.tanggal"
                :error-messages="errors.collect('Tanggal')"
                v-validate="'required'"
              />
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                label="Nama"
                name="Nama"
                v-model="input.nama"
                :error-messages="errors.collect('Nama')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
            <v-flex
              xs12
              md6
              class="px-2"
            >
              <v-text-field
                label="Jabatan"
                name="Jabatan"
                v-model="input.jabatan"
                :error-messages="errors.collect('Jabatan')"
                v-validate="'required'"
              ></v-text-field>
            </v-flex>
          </v-layout>
        </v-card>
        <v-divider></v-divider>
        <v-card
          flat
          class="pa-3"
        >
          <v-btn
            color="success"
            @click="submit()"
          >Simpan</v-btn>
          <v-btn
            color="error"
            @click="cancel()"
          >Batal</v-btn>
        </v-card>
      </v-form>
    </v-flex>
  </div>
</template>

<script>
import moment from "moment";

export default {
  props: {
    type: {
      type: String
    },
    data: {
      type: Object
    },
    idJenis: {}
  },
  data: () => ({
    input: {
      periode: "",
      tempat: "",
      tanggal: "",
      nama: "",
      jabatan: ""
    }
  }),
  created() {
    if (this.type === "edit") {
      this.input = {
        periode: this.data.periode,
        tempat: this.data.tempat,
        tanggal: this.data.tanggal,
        nama: this.data.nama,
        jabatan: this.data.jabatan
      };
    }
  },
  methods: {
    submit() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          this.$http
            .post("base/service/executeMutation", this.inputParams)
            .then(response => {
              if (response.data.success_message) {
                this.$vuedals.close(true);
              }
            });
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    },
    cancel() {
      this.$vuedals.close(false);
    }
  },
  computed: {
    mutationType() {
      const mutationType = this.type === "edit" ? "update" : "insert";
      return mutationType;
    },
    inputData() {
      const data = {
        periode: this.input.periode,
        tempat: this.input.tempat,
        tanggal: moment(this.input.tanggal).format("YYYY-MM-DD"),
        nama: this.input.nama,
        jabatan: this.input.jabatan,
        jenis: this.idJenis
      };
      return data;
    },
    inputParams() {
      const params = {
        id: undefined,
        type: this.mutationType,
        name: "setting_print",
        data: this.inputData
      };
      if (this.type === "edit") params.id = this.data.id;
      return params;
    }
  }
};
</script>

<style lang="css">
</style>



